import raw from "../../../shared/deployments/31337.json";

export interface Deployment {
  contractName: string;
  chainId: number;
  address: `0x${string}`;
  deployedAt: string;
  deployer: `0x${string}`;
  boardId?: string;
  roles: {
    admin?: `0x${string}`;
    supplier: `0x${string}`;
    assembler: `0x${string}`;
    auditor: `0x${string}`;
    custodian: `0x${string}`;
  };
  demo?: {
    boardId: string;
    componentIds: string[];
    expected: { compliant: boolean; missing: string[] };
  };
  abi: readonly unknown[];
}

/**
 * Generated by `scripts/seed.ts` (or `scripts/deploy.ts`). Vite watches the
 * file, so redeploying and reseeding hot-reloads the address and ABI. Never
 * hand-copy an address into a component.
 */
export const deployment = raw as unknown as Deployment;

export const RPC_URL =
  (import.meta.env.VITE_RPC_URL as string | undefined) ??
  `http://127.0.0.1:8545`;
